import os
import urllib.parse
import requests
from PIL import Image, ImageDraw, ImageFilter

def fetch_scene_visuals(scenes: list, video_type: str, out_dir: str) -> list:
    os.makedirs(out_dir, exist_ok=True)
    w, h = (1080, 1920) if video_type == "short" else (1920, 1080)
    paths = []

    for idx, scene in enumerate(scenes):
        img_path = os.path.join(out_dir, f"scene_{idx:02d}.jpg")
        # Extract precise visual query generated by script engine matching the exact topic sentence
        raw_query = scene.get("visual_query_en", "lord shiva spiritual temple")
        # Enhance with high-end photographic descriptors for professional cinematic HD quality
        query = f"{raw_query}, photorealistic, 8k resolution, cinematic lighting, highly detailed, sacred Indian spiritual art"
        
        downloaded = False
        try:
            # High quality topic-matched image fetch via Pollinations AI HD prompt engine
            encoded_q = urllib.parse.quote(query)
            img_url = f"https://image.pollinations.ai/prompt/{encoded_q}?width={w}&height={h}&nologo=true&seed={idx+777}"
            r = requests.get(img_url, timeout=25)
            if r.status_code == 200 and len(r.content) > 12000:
                with open(img_path, "wb") as f:
                    f.write(r.content)
                Image.open(img_path).verify()
                downloaded = True
        except Exception:
            pass

        # Professional Fallback with Deep Devotional Saffron/Temple Palette and Vignette
        if not downloaded:
            img = Image.new("RGB", (w, h), (15, 10, 25))
            draw = ImageDraw.Draw(img)
            for y in range(h):
                f = y / h
                rc = int(210 * (1 - f) + 30 * f)
                gc = int(100 * (1 - f) + 15 * f)
                bc = int(20 * (1 - f) + 50 * f)
                draw.line([(0, y), (w, y)], fill=(rc, gc, bc))
            img.save(img_path, "JPEG", quality=95)
        else:
            try:
                im = Image.open(img_path).convert("RGB")
                im = im.resize((w, h), Image.Resampling.LANCZOS)
                # Clean golden professional border framing
                draw = ImageDraw.Draw(im)
                draw.rectangle([(0, 0), (w, h)], outline=(255, 215, 0), width=6)
                im.save(img_path, "JPEG", quality=95)
            except Exception:
                pass

        paths.append(img_path)
    return paths
